blocks.code:
p {
  line-height: 1.6;
}

.card {
  padding: 1rem;
}

#featured-card {
  border-color: rebeccapurple;
}

.card p {
  color: #334155;
}

/* Оба селектора могут совпасть с заголовком выделенной карточки. */
.card__title {
  color: #2563eb;
}

#featured-card .card__title {
  color: #7c3aed;
}

/* styles.css */
*, *::before, *::after {
  box-sizing: border-box;
}

.card {
  width: 320px;
  padding: 16px;
  border: 2px solid #cbd5e1;
  margin-block: 12px;
}

.card__title {
  color: #2563eb;
}

#featured-card .card__title {
  color: #7c3aed;
}

.card p {
  color: slateblue;
  width: 320px;
  padding: 16px;
  border: 2px solid;
}

#app .card p {
  color: darkgreen;
}

* {
  box-sizing: border-box;
}

